from lib import *
S = SS('f47')
R = J('f47'); sz = R['size']
steps = [
    step(f"签名后的值是 payload.timestamp.signature 三段 URL 安全的 base64:这里 token = {R['token']}。第 1 段解码得到 JSON {R['payload']};第 2 段解码是整数 {R['ts']}(2026-10-02T03:29:07+00:00 的 Unix 时间戳);第 3 段解码是 {R['sig_len']} 字节(HMAC-SHA1)。payload 没有加密,任何拿到 cookie 的人都能读;签名只保证内容没有被改过。", t=tl(S(1)), done=lidx(S(1), 'token =', '第 1 段', '第 2 段'), mark=lidx(S(1), '第 3 段', '结论'), kv=KV([['结构', 'payload.timestamp.signature'], ['payload', 'base64 明文,没加密'], ['签名', 'HMAC-SHA1,20 字节']], ['payload'])),
    step(f"按 itsdangerous 的算法手工算一遍:派生密钥 = sha1(salt + b'signer' + secret_key)(前 8 字节 {R['key_head']}),签名 = base64url(HMAC-SHA1(派生密钥, 'payload.timestamp'))。手算结果与 token 里的签名完全相同:{R['manual_ok']}。", t=tl(S(2)), done=lidx(S(2), '手算签名', 'token 里的签名'), mark=lidx(S(2), '相同: True'), kv=KV([['密钥派生', 'sha1(salt + \"signer\" + secret)'], ['签名', 'HMAC-SHA1(派生密钥, payload.timestamp)'], ['手算与库', '一致']], ['手算与库'])),
    step("篡改与伪造:原样通过(得到 {'uid': 42, 'role': 'admin'});改 payload、改时间戳、换密钥、换 salt、截断签名都抛 BadTimeSignature「Signature … does not match」;去掉签名段抛 BadSignature;随机字符串抛 BadSignature「No b'.' found in value」。伪造别人的 token 需要知道密钥与 salt。", t=tl(S(3)), done=lidx(S(3), '原样'), mark=lidx(S(3), '改 payload', '改时间戳', '另一个密钥', '另一个 salt', '截断', '随机字符串'), kv=KV([['任何一处被改', 'BadTimeSignature / BadSignature'], ['密钥或 salt 不同', '验证失败']], ['任何一处被改'])),
    step(f"过期:loads(max_age=10) 通过,max_age=1 抛 SignatureExpired「Signature age 3 > 1 seconds」,异常里 date_signed = {R['expired'][0]} 且 payload(base64 形式 {R['expired'][1]})仍然可取;不传 max_age 就永不过期。过期判断在验证时做,时间戳是签名时写进去的。", t=tl(S(4)), done=lidx(S(4), 'max_age=10'), mark=lidx(S(4), 'max_age=1', 'SignatureExpired', '不传 max_age'), kv=KV([['max_age=10', '通过'], ['max_age=1(已过 3 秒)', 'SignatureExpired'], ['不传 max_age', '永不过期']], ['max_age=1(已过 3 秒)'])),
    step("在 Flask 里做「记住我」cookie:登录时 set_cookie('remember', ser.dumps({'uid': 7}), max_age=3600, httponly=True, samesite='Lax');GET /me 读出来验证,得到 200 {'uid': 7};把 payload 换成伪造的 {uid:1, role:root} 后签名对不上,得到 401 {'error': 'bad signature'}。", t=tl(S(5)), done=lidx(S(5), 'Set-Cookie 的第一段', 'GET /me →'), mark=lidx(S(5), '篡改 payload 后'), kv=KV([['正常', '200 uid=7'], ['篡改 payload', '401 bad signature']], ['篡改 payload'])),
    step("没有撤销:签名 cookie 在有效期内一直有效。客户端登出(删 cookie)后,如果别人拿着旧 token 再发,服务器照样返回 200 —— 服务器端没有状态,无从知道它已经「登出」。需要撤销就要加服务端状态(版本号、黑名单)。", t=tl(S(6)), done=lidx(S(6), '登出'), kv=KV([['旧 token 继续发', '200(仍然有效)'], ['撤销', '要服务端状态']], ['旧 token 继续发'])),
    step(f"大小与压缩:URLSafe 序列化器在压缩后更短时用 zlib 压缩(token 以 . 开头)。10 个随机十六进制字符的 payload(JSON {sz['10 字符的随机十六进制'][0]} 字节)→ token {sz['10 字符的随机十六进制'][1]} 字符,未压缩;100 个随机十六进制字符(JSON {sz['100 字符的随机十六进制'][0]})→ {sz['100 字符的随机十六进制'][1]} 字符(已压缩);1000 个(JSON {sz['1000 字符的随机十六进制'][0]})→ {sz['1000 字符的随机十六进制'][1]} 字符;100 个重复的 x → {sz['100 个重复的 x'][1]} 字符,1000 个重复的 x → {sz['1000 个重复的 x'][1]} 字符。短 payload 的固定开销约 39 字符(时间戳 + 签名 + base64)。", t=tl(S(7)), done=lidx(S(7), '10 字符的随机十六进制', '100 字符的随机十六进制'), mark=lidx(S(7), '重复的 x'), kv=KV([['10 字符 payload', f"token {sz['10 字符的随机十六进制'][1]} 字符(无压缩)"], ['1000 个重复 x', f"token {sz['1000 个重复的 x'][1]} 字符(压缩)"]], ['1000 个重复 x'])),
]
A = mkartf('f47', 47, 'Flask,签名 Cookie,itsdangerous,HMAC,真实验证,动画演示',
    '用 itsdangerous 验证签名 cookie:payload.timestamp.signature 三段,payload 明文可读;手工按 sha1 派生密钥 + HMAC-SHA1 算出一致的签名;改任何一处、换密钥或 salt 都验证失败;max_age 过期;Flask 里做「记住我」cookie;没有撤销;压缩与大小开销。',
    'Flask 的 session 与「记住我」cookie 靠什么保证不被篡改?值里到底装了什么?能不能自己算出签名?过期和撤销怎么处理?这篇把 itsdangerous 的算法手工复现一遍。',
    [('3 段', '签名后 token 的段数:payload、timestamp、signature'), ('20 字节', 'HMAC-SHA1 签名的长度'), ('明文', 'payload 的状态(没有加密,只是签名)')],
    [('签名后的结构', '<p>上一篇:<a href="flask-cookie-read-write.html">Cookie 的读写过程</a>;下一篇:<a href="flask-session-cookie-structure.html">Session Cookie 的数据结构</a>;SECRET_KEY 的用途:<a href="flask-secret-key-usage.html">SECRET_KEY 的用途</a>。</p>'), ('手工复现签名', None), ('篡改与伪造', None), ('过期', None), ('Flask 里的使用', None), ('没有撤销', None), ('大小与压缩', None)],
    steps, [ENV_F + '。itsdangerous 2.2.0', '没有验证:Fernet 等加密方案(本篇的签名不加密)、签名算法换成 SHA-256 的方式、SECRET_KEY_FALLBACKS 轮换(见第 187 篇)、时钟漂移对 max_age 的影响'], '签名 cookie')
